float sdCorners(vec2 p, vec2 s, float r, vec2 i) {
  vec2 uv = abs(p) + min(s, i);
  vec2 crst = uv - min(s, i) * 2.;
  float cr = min(crst.x, crst.y);
  vec2 d = abs(p) - s;
  float rect = min(max(d.x, d.y), 0.0) + length(max(d, 0.0)) - r;
  float cap = min(
    length(abs(p) - vec2(min(s.x, i.x), s.y + r)),
    length(abs(p) - vec2(s.x + r, min(s.y, i.y)))
  );
  float sd = mix(abs(rect), cap, step(cr, 0.0));
  return sd;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  uv = (uv - .5) * vec2(iResolution.x / iResolution.y, 1) + .5;
  float sd = sdCorners(
    uv - .5,
    vec2(.4, .2), // size
    mix(.0, .2, sin(iTime)*.5+.5), // rounding
    mix(vec2(.1), vec2(.15), vec2(cos(iTime), sin(iTime))*.5+.5) // inset
  );
  sd = 1.-exp(-sd*8.) + (sin(sd*88.)*.5+.5)*.1;
  fragColor = vec4(sd, sd, sd, 1);
}
